from pathlib import Path
import collections, datetime, hashlib, json, re, subprocess
from urllib.parse import unquote
ROOT=Path('/Users/wkoch/Projetos/xrai')
DOCS=['IMPLEMENTADOR.md','README.md','docs/PLANO-DE-IMPLEMENTACAO.md','docs/PLANO-DE-VALIDACAO.md','docs/RFC-0001-ARQUITETURA.md','docs/STATUS-IMPLEMENTACAO.md','docs/decisoes/CORPUS-QUALIFICADO.md','docs/ROTEIRO-V1.md','docs/relatorios/REVISAO-L5-CONTINUACAO.md']
EVIDENCE='docs/relatorios/logs/revisao-v1/evidencias.json'
OUTPUT='docs/relatorios/logs/revisao-v1/documentacao.json'
def git(*args): return subprocess.check_output(['git',*args],cwd=ROOT,text=True)
def read(p): return (ROOT/p).read_text()
def old(p): return git('show','HEAD:'+p)
def cards(text,prefix):
 matches=list(re.finditer(r'^### ('+prefix+r'-\d+(?:\.R\d+)?) —[^\n]+',text,re.M))
 result={}
 for i,m in enumerate(matches):
  block=text[m.end():matches[i+1].start() if i+1<len(matches) else len(text)]
  dep=re.search(r'\*\*Depende de:\*\* ([^\n]+)',block).group(1).split(' **')[0]
  result[m.group(1)]={'heading':m.group(0),'dependency_text':dep,'dependencies':re.findall(r'(?:M[01]|V1)-\d+(?:\.R\d+)?',dep)}
 return result
def states(t): return dict(re.findall(r'^\| (M[01]-\d+(?:\.R\d+)?) \| [^|]+ \| ([^|]+?) \|',t,re.M))
plan=cards(read(DOCS[2]),'M[01]'); assert plan==cards(old(DOCS[2]),'M[01]') and len(plan)==41
status=states(read(DOCS[5])); assert status==states(old(DOCS[5])) and set(status)==set(plan)
counts=dict(collections.Counter(status.values())); assert counts=={'concluída':9,'em andamento':7,'não iniciada':25},counts
gates=re.findall(r'^\| (G[012]) \| ([^|]+?) \|',read(DOCS[5]),re.M)
assert gates==[('G0','não avaliado'),('G1','não avaliado'),('G2','não avaliado')]
future=cards(read(DOCS[7]),'V1'); assert set(future)=={f'V1-{i:02d}' for i in range(1,7)}
combined=plan|future
for key,card in combined.items(): assert set(card['dependencies'])<=set(combined),(key,card)
def ancestors(key,active=()):
 assert key not in active,('cycle',active,key)
 result=set()
 for dep in combined[key]['dependencies']:result|={dep}|ancestors(dep,active+(key,))
 return result
for key in combined: ancestors(key)
for key in future: assert 'M1-21' in ancestors(key)
assert 'seis cartões novos são condicionais e ainda não iniciados' in read(DOCS[7])
links=[]
for name in DOCS:
 for target in re.findall(r'\[[^\]]*\]\(([^)]+)\)',read(name)):
  target=target.strip('<>')
  if re.match(r'^[a-zA-Z]+:',target) or target.startswith('#'):continue
  target=unquote(target.split('#')[0])
  path=(ROOT/name).parent/target
  assert path.exists() or path.resolve()==(ROOT/OUTPUT).resolve(),(name,target)
  links.append({'source':name,'target':target})
allowed=set(DOCS+[EVIDENCE,OUTPUT])
changed=set(git('diff','--name-only').splitlines())|set(git('ls-files','--others','--exclude-standard').splitlines())
assert changed<=allowed,sorted(changed-allowed)
assert not git('diff','--cached','--name-only').strip(),'pre-existing staging requires review'
check=subprocess.run(['git','diff','--check'],cwd=ROOT,text=True,capture_output=True);assert check.returncode==0,check.stdout+check.stderr
receipt=json.loads(read(EVIDENCE));assert receipt['result']=='passed' and receipt['retained_files_verified']==55 and receipt['publication_sources_verified']==8
assert len(receipt['commands'])==3 and all(x['exit_code']==0 for x in receipt['commands'])
assert sum(x['recorded_binary_hashes'] for x in receipt['native_receipt_summaries'].values())==12
for path in ['docs/decisoes/CORPUS-QUALIFICADO.md','docs/PLANO-DE-VALIDACAO.md','docs/relatorios/REVISAO-L5-CONTINUACAO.md']:assert 'C02' in read(path)
assert '0/32' in read(DOCS[7]) and '0/4' in read(DOCS[8])
files={p:{'bytes':(ROOT/p).stat().st_size,'sha256':hashlib.sha256((ROOT/p).read_bytes()).hexdigest()} for p in DOCS+[EVIDENCE]}
report={'schema':'xrai.architecture.v1-progress.documentation.v1','at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'base_commit':git('rev-parse','HEAD').strip(),'result':'passed','checks':{'existing_cards_and_dependency_text_preserved':41,'existing_states_preserved':counts,'gates':dict(gates),'new_conditional_cards':future,'all_new_cards_transitively_depend_on_G2_card':True,'dependency_graph_acyclic':True,'local_link_targets_checked':len(links),'changed_files_within_documentation_scope':True,'diff_check_exit_code':0,'evidence_data_only_commands_passed':3},'files':files,'verifier_source':Path(__file__).read_text(),'limits':['Checks validate documentary structure, local link targets and prior receipt consistency, not implementation of new release criteria.','No build, native executable, upstream behavioral test, agent campaign or paid session run by this documentary verifier.','No release approval; existing task states/gates and corpus data files unchanged.']}
(ROOT/OUTPUT).write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n')
print(json.dumps({'result':'passed','cards':41,'new_conditional_cards':6,'local_links':len(links),'counts':counts,'receipt':OUTPUT},ensure_ascii=False))
